export function EscalationIndicator({
  label = "{{label}}",
  level = "{{level}}",
  pulsing = {{pulsing}},
  minutesOpen = {{minutesOpen}},
}) {
  const palette = {
    low: { color: "#2F6FA8", background: "color-mix(in srgb, #2F6FA8 12%, #FAF7F2)" },
    medium: { color: "#8A5A08", background: "color-mix(in srgb, #8A5A08 12%, #FAF7F2)" },
    high: { color: "#B3541E", background: "color-mix(in srgb, #B3541E 14%, #FAF7F2)" },
    critical: { color: "#FAF7F2", background: "#8C1F17" },
  }[level] ?? { color: "#2F6FA8", background: "#FAF7F2" };
  return (
    <div role="status" style={{ display: "inline-flex", alignItems: "center", gap: 8, padding: "6px 12px",
      borderRadius: 999, fontWeight: 600, fontSize: 12.5, boxSizing: "border-box", border: `1.5px solid ${palette.color}`,
      color: palette.color, background: palette.background }}>
      <span aria-hidden="true" className={pulsing ? "esc-pulse-dot" : undefined} style={{ width: 8, height: 8, borderRadius: "50%", background: "currentColor", flexShrink: 0 }} />
      <span>{label}</span>
      <span style={{ opacity: 0.75, fontWeight: 500 }}>{minutesOpen}m open</span>
      <style>{`@media (prefers-reduced-motion: no-preference) { .esc-pulse-dot { animation: escalation-react-pulse .22s ease-in-out infinite; } } @keyframes escalation-react-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .55; } }`}</style>
    </div>
  );
}
